def build_coloring_prompt(subject):
    return (
        f"Clean black and white coloring book page line art on pure white paper, "
        f"publication-quality storybook coloring illustration of {subject}, "
        f"delicate uniform monoline inking, crisp thin black outlines, large open hollow white spaces everywhere for coloring in, "
        f"hollow white hair with neat black contours, strictly zero solid black hair fills, strictly zero shading, "
        f"strictly zero grayscale, strictly zero color, strictly zero crosshatching, strictly zero gradients, "
        f"clean closed contours for digital bucket fill, pure white background"
    )

def main():
    items = []
    category_counts = {}

    for category, prompt_tuples in DATA.items():
        category_counts[category] = len(prompt_tuples)
        for item_id, title, subject, difficulty, tags in prompt_tuples:
            full_prompt = build_coloring_prompt(subject)
            cultural_story = f"Honoring Black excellence, leadership, and enduring impact in {category}. Celebrating cultural pride, ingenuity, and community inspiration."
            items.append({
                "id": item_id,
                "category": category,
                "title": title,
                "subject": subject,
                "culturalStory": cultural_story,
                "prompt": full_prompt,
                "difficulty": difficulty,
                "tags": tags
            })

    print(f"Total categories: {len(DATA)}")
    for cat, count in category_counts.items():
        print(f"  {cat}: {count} prompts")
    print(f"Total prompts generated: {len(items)}")

    # Ensure output dir exists
    out_dir = os.path.join("src", "data")
    os.makedirs(out_dir, exist_ok=True)

    # 1. Write JSON file
    json_path = os.path.join(out_dir, "communityPrompts.json")
    with open(json_path, "w", encoding="utf-8") as f:
        json.dump(items, f, indent=2, ensure_ascii=False)
    print(f"Successfully saved JSON to {json_path}")

    # 2. Write TypeScript file
    ts_path = os.path.join(out_dir, "communityPrompts.ts")
    with open(ts_path, "w", encoding="utf-8") as f:
        f.write("export interface CommunityPromptItem {\n")
        f.write("  id: string;\n")
        f.write("  category: 'celebrity' | 'scientists' | 'engineers' | 'healthcare' | 'children' | 'teenagers' | 'adults' | 'cosmic';\n")
        f.write("  title: string;\n")
        f.write("  subject: string;\n")
        f.write("  culturalStory: string;\n")
        f.write("  prompt: string;\n")
        f.write("  difficulty: 'Easy' | 'Medium' | 'Detailed';\n")
        f.write("  tags: string[];\n")
        f.write("}\n\n")
        f.write(f"export const COMMUNITY_PROMPTS: CommunityPromptItem[] = {json.dumps(items, indent=2, ensure_ascii=False)};\n\n")
        f.write("export const PROMPT_CATEGORIES = [\n")
        for cat in DATA.keys():
            f.write(f"  '{cat}',\n")
        f.write("] as const;\n\n")
        f.write("export type PromptCategory = typeof PROMPT_CATEGORIES[number];\n")
    print(f"Successfully saved TypeScript to {ts_path}")

if __name__ == "__main__":
    main()
